export const ENEMY_POOL = {"fight":["slimeG","slimeV","skelett","bat","batR","goblin","pilz","ratte","spinne","zombie","imp","schlange","kaefer","irrlicht","kroete","mumie","slimeF","spinneF","goblinR","skelettR"],"irregular":["mimic","geist","auge","gargoyle","ruestung","buch","kristall","schatten"],"boss":["lich","drache","minotaurus","golem","vampir","hexe","slimeK","spinneK"]};
export function dungeonEnemySVG(key) {
  const sp = DUNGEON_ENEMIES[key]; if (!sp) return '';
  let rects = '';
  sp.r.forEach((row, y) => { let x = 0; row.replace(/(\D)(\d*)/g, (m, ch, n) => { const k = n ? +n : 1, i = ALPHA.indexOf(ch); if (i >= 0) rects += `<rect x="${x}" y="${y}" width="${k}" height="1" fill="${sp.p[i]}"/>`; x += k; return m; }); });
  return `<svg viewBox="0 0 ${sp.w} ${sp.h}" shape-rendering="crispEdges" style="width:100%;height:100%;display:block;image-rendering:pixelated;" aria-hidden="true">${rects}</svg>`;
}
// Gleiche Signatur wie bisher: kind = 'fight' | 'irregular' | 'boss'.
export function enemySpriteSVG(kind) { const pool = ENEMY_POOL[kind] || ENEMY_POOL.fight; return dungeonEnemySVG(pool[Math.floor(Math.random() * pool.length)]); }

